package net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RegisteredEmailTemplateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property registered email template of tenant config ")
  void test_registered_email_template_v_o_builder() {
    Assertions.assertFalse(
        RegisteredEmailTemplateVO.nullValue().getRegisteredEmailTemplate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        RegisteredEmailTemplateVO.tryFrom(null).getRegisteredEmailTemplate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        RegisteredEmailTemplateVO.from("one").getRegisteredEmailTemplate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RegisteredEmailTemplateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RegisteredEmailTemplateVO.from("one").toString());
  }
}
